pub const CONVERSATIONS_MCP_DEFAULT_BASE_PATH: &str = "/telividb/conversation/v1/conversations/mcp";

pub struct ConversationsMcpTransportConfig {
    pub transport: String,
    pub host: String,
    pub port: u16,
    pub base_path: String,
}

impl Default for ConversationsMcpTransportConfig {
    fn default() -> Self {
        Self {
            transport: "streamable-http".into(),
            host: "0.0.0.0".into(),
            port: 8080,
            base_path: CONVERSATIONS_MCP_DEFAULT_BASE_PATH.into(),
        }
    }
}

pub async fn serve_conversations_mcp_stdio<T: ConversationsMcpServer>(
    svc: T,
) -> std::result::Result<(), Box<dyn std::error::Error>> {
    let handler = ConversationsMcpHandler::new(svc);
    handler
        .serve(rmcp::transport::stdio())
        .await?
        .waiting()
        .await?;
    Ok(())
}

pub async fn serve_conversations_mcp<T: ConversationsMcpServer>(
    svc: T,
    config: ConversationsMcpTransportConfig,
) -> std::result::Result<(), Box<dyn std::error::Error>> {
    let handler = ConversationsMcpHandler::new(svc);
    let transports: Vec<&str> = config
        .transport
        .split(',')
        .map(|s| s.trim())
        .filter(|s| !s.is_empty())
        .collect();
    let has_stdio = transports.iter().any(|t| *t == "stdio");
    let http_transport = transports
        .iter()
        .find(|t| **t == "sse" || **t == "streamable-http")
        .copied();

    if let Some(_ht) = http_transport {
        use rmcp::transport::streamable_http_server::{
            StreamableHttpServerConfig, StreamableHttpService, session::local::LocalSessionManager,
        };
        let h = handler.clone();
        let http_config = StreamableHttpServerConfig::default().with_sse_retry(None);
        let http_service = StreamableHttpService::new(
            move || Ok(h.clone()),
            Arc::new(LocalSessionManager::default()),
            http_config,
        );
        let app = axum::Router::new().nest_service(&config.base_path, http_service);
        let addr = format!("{}:{}", config.host, config.port);
        let listener = tokio::net::TcpListener::bind(&addr).await?;
        if has_stdio {
            tokio::spawn(async move {
                axum::serve(listener, app)
                    .await
                    .expect("HTTP server failed");
            });
        } else {
            axum::serve(listener, app).await?;
            return Ok(());
        }
    }

    if has_stdio {
        handler
            .serve(rmcp::transport::stdio())
            .await?
            .waiting()
            .await?;
    } else if http_transport.is_none() {
        return Err(format!("unsupported transport(s): {}", config.transport).into());
    }
    Ok(())
}
